    # count the number of letters in the string
    num_letters = sum(1 for char in s if char.isalpha())

    if num_letters == 0:
        return s[::-1]

    result = []
    # apply the case reversal logic
    for char in s:
        if char.isalpha():
            if char in vowels:
                result.append(char.lower())
            else:
                result.append(char.upper())
        else:
            result.append(char)

    return ''.join(result)
